context_info = ""
i = 0
for d in context:
    i = i + 1
    result = llm_query("You will be given one document. Task: Determine if it mentions an athlete who matches ALL or MOST of these traits, and extract personal-best data:\nTraits to match:\n- Born in the 1970s\n- Three-time World Half-Marathon champion\n- Won their first race at age 21\n- Honored by the UN as Person of the Year in their country\n- Weighed about 40 kg as of February 2018\n- Retired from professional running by 2021\n\nIf the document mentions such an athlete (e.g., Tegla Loroupe, Paula Radcliffe, Lornah Kiplagat), identify the athlete and extract:\n- Athlete name\n- Evidence quotes linking to each trait (as available)\n- 10,000 m personal best time AND the exact date (day, month, year) when that PB was set (explicitly stated in the doc). If date not explicit, provide any date clues tied to the PB.\n- Any table or infobox entries related to PBs\n\nReturn a compact, structured summary.\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT")
    context_info = context_info + "\n\n[DOC " + str(i) + " ANALYSIS]\n" + result

final_answer = llm_query("You are given extractions from several documents. From these, determine which athlete matches ALL the query clues and then provide the exact calendar date (day, month, year) when that athlete achieved their personal-best performance in the 10,000 m event.\n\nQuery clues:\n- Born in the 1970s\n- Three-time World Half-Marathon champion\n- Won their first race at 21\n- Honored by the UN as Person of the Year in their country\n- As of February 2018, weighed 40 kg\n- As of 2021, retired from professional running\n\nLikely candidate includes Tegla Loroupe; confirm using the extracts. Then, from the matching document excerpts, extract the exact date (day, month, year) of the 10,000 m personal best. If multiple dates are shown, choose the one explicitly tied to the 10,000 m PB of the matched athlete.\n\nProvide ONLY the date in the format: D Month YYYY (e.g., 7 October 1998). No extra text.\n\nBEGIN_EXTRACTS\n" + context_info + "\nEND_EXTRACTS")
return_result(final_answer)